class QuoteIdleProbe {
  static final Map<String, int> _counts = <String, int>{};
  static Timer? _timer;

  static void start() {
    if (kReleaseMode) return;
    _timer ??= Timer.periodic(const Duration(minutes: 1), (_) {
      debugPrint('[QuoteIdleProbe] per minute: $_counts');
      _counts.clear();
    });
  }

  static void stop() { _timer?.cancel(); _timer = null; }

  static void hit(String name) {
    if (kReleaseMode) return;
    _counts[name] = (_counts[name] ?? 0) + 1;
  }
}

